"""Compare the ctypes layout with the sizes and offsets the C compiler produced.

AOAHID_ABI_ORACLE names the built layout_oracle program.
"""

from __future__ import annotations

import os
import subprocess
import sys

import aoahid.native as native


def oracle() -> dict[str, int]:
    path = os.environ.get("AOAHID_ABI_ORACLE")
    if not path:
        raise SystemExit("AOAHID_ABI_ORACLE is not set")
    text = subprocess.run([path], check=True, capture_output=True, text=True).stdout
    return {k: int(v) for k, v in (line.split("=", 1) for line in text.splitlines())}


